create table if not exists public.categories (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,category_name text not null,description text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,category_name));
create table if not exists public.units (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,unit_name text not null,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,unit_name));
create table if not exists public.taxes (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,rate numeric(8,4) not null default 0,sub_tax text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.box_sizes (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,name));
create table if not exists public.parties (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text,email text,type text not null default 'Retailer',phone text,due numeric(12,2) not null default 0,opening_balance numeric(12,2) not null default 0,address text,image text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists parties_business_phone_uq on public.parties(business_id,phone) where phone is not null;
create table if not exists public.products (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_name text not null,category_id bigint references public.categories(id) on delete set null,unit_id bigint references public.units(id) on delete set null,type_id bigint,manufacturer_id bigint,box_size_id bigint references public.box_sizes(id) on delete set null,purchase_without_tax numeric(14,4) not null default 0,purchase_with_tax numeric(14,4) not null default 0,profit_percent numeric(8,4) not null default 0,sales_price numeric(14,4) not null default 0,alert_qty integer not null default 0,wholesale_price numeric(14,4) not null default 0,product_code text,images text,tax_id bigint references public.taxes(id) on delete set null,tax_type text not null default 'exclusive',meta text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,product_code));
create index if not exists products_business_name_idx on public.products(business_id,product_name);
create table if not exists public.warehouses (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,name text not null,code text not null,location text,is_default boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,code));
create table if not exists public.warehouse_stocks (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,warehouse_id bigint not null references public.warehouses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,quantity integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(warehouse_id,product_id));
create table if not exists public.stocks (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,product_stock integer not null default 0,batch_no text,expire_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists stocks_business_product_idx on public.stocks(business_id,product_id);
create index if not exists stocks_business_expiry_idx on public.stocks(business_id,expire_date);
do $$ declare t text; begin for t in select unnest(array['categories','units','taxes','box_sizes','parties','products','warehouses','warehouse_stocks','stocks']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon, authenticated',t); execute format('grant select, insert, update, delete on table public.%I to authenticated',t); execute format('create policy %I_select on public.%I for select to authenticated using (business_id = (select public.current_business_id()))',t||'_tenant_select',t); execute format('create policy %I_insert on public.%I for insert to authenticated with check (business_id = (select public.current_business_id()))',t||'_tenant_insert',t); execute format('create policy %I_update on public.%I for update to authenticated using (business_id = (select public.current_business_id())) with check (business_id = (select public.current_business_id()))',t||'_tenant_update',t); execute format('create policy %I_delete on public.%I for delete to authenticated using (business_id = (select public.current_business_id()))',t||'_tenant_delete',t); end loop; end $$;